#include "../ring3_common.hpp"
static constexpr u32 W=420,H=470;static u32*pix;static u64 events,win;static char expr[192],result[64];static u32 n;static bool dirty=true;
struct P{const char*p;bool ok;static bool d(char c){return c>='0'&&c<='9';}i64 num(){while(*p==' ')p++;bool neg=false;if(*p=='-'){neg=true;p++;}if(!d(*p)){ok=false;return 0;}i64 v=0;while(d(*p))v=v*10+(*p++-'0');return neg?-v:v;}i64 factor(){while(*p==' ')p++;if(*p=='('){p++;i64 v=sum();while(*p==' ')p++;if(*p==')')p++;else ok=false;return v;}return num();}i64 term(){i64 v=factor();while(ok){while(*p==' ')p++;char o=*p;if(o!='*'&&o!='/')break;p++;i64 r=factor();if(o=='*')v*=r;else if(!r){ok=false;return 0;}else v/=r;}return v;}i64 sum(){i64 v=term();while(ok){while(*p==' ')p++;char o=*p;if(o!='+'&&o!='-')break;p++;i64 r=term();v=o=='+'?v+r:v-r;}return v;}};
static void out(i64 v){char t[40];u32 z=0,o=0;bool neg=v<0;u64 x=neg?(u64)(-(v+1))+1:(u64)v;if(!x)t[z++]='0';while(x){t[z++]=(char)('0'+x%10);x/=10;}if(neg)result[o++]='-';while(z)result[o++]=t[--z];result[o]=0;}
static void eval(){P p{expr,true};i64 v=p.sum();while(*p.p==' ')p.p++;if(!p.ok||*p.p){const char*e="ERROR";u32 i=0;for(;e[i];i++)result[i]=e[i];result[i]=0;}else out(v);dirty=true;}
static void press(char c){if(c=='C'){n=0;expr[0]=0;result[0]='0';result[1]=0;}else if(c=='B'){if(n)expr[--n]=0;}else if(c=='=')eval();else if(n<190){expr[n++]=c;expr[n]=0;}dirty=true;}
static const char keys[20]={'C','B','(',')','7','8','9','/','4','5','6','*','1','2','3','-','0','0','=','+'};
static void draw(){fill(pix,W*H,0x00e8eef3);rect(pix,W,H,0,0,W,48,0x002a5f9e);text(pix,W,H,16,15,"DAVIS CALCULATOR  RING 3",0x00ffffff,2);rect(pix,W,H,18,62,W-36,54,0x00ffffff);text(pix,W,H,28,78,expr[0]?expr:"0",0x00182030,2);rect(pix,W,H,18,124,W-36,58,0x00d8e9d6);text(pix,W,H,28,138,"RESULT",0x00306040,1);text(pix,W,H,28,156,result[0]?result:"0",0x00183020,2);for(int i=0;i<20;i++){int r=i/4,c=i%4;int x=18+c*96,y=196+r*50;rect(pix,W,H,x,y,86,40,0x00ffffff);char z[2]={keys[i],0};text(pix,W,H,x+36,y+14,z,0x00182030,2);}text(pix,W,H,20,H-18,"KEYBOARD OR POINTER   ENTER EVALUATES",0x00485465,1);sc(SYS_PRESENT,win,(u64)pix,(u64)W*H*4);dirty=false;}
extern "C" __attribute__((section(".text.entry"))) void _davis_start(){pix=(u32*)(u64)sc(SYS_ALLOC,(u64)W*H*4);if(!pix)sc(0,1);win=makeWindow(events,W,H,820,150);if(!win)sc(0,2);result[0]='0';result[1]=0;for(;;){Wire m{};while(sc(SYS_IPC_RECV,events,(u64)&m)>0){if(m.type==KEY&&m.bytes==sizeof(KeyEv)){char c=(char)((KeyEv*)m.payload)->codepoint;if(c=='\r')c='=';if(c=='\b')c='B';if((c>='0'&&c<='9')||c=='+'||c=='-'||c=='*'||c=='/'||c=='('||c==')'||c=='='||c=='B')press(c);}else if(m.type==POINTER&&m.bytes==sizeof(PtrEv)){auto*q=(PtrEv*)m.payload;if(q->flags&2){if(q->y>=196&&q->y<446&&q->x>=18&&q->x<402){int c=(q->x-18)/96,r=(q->y-196)/50;if(c>=0&&c<4&&r>=0&&r<5)press(keys[r*4+c]);}}}else if(m.type==CLOSE)sc(0,0);}if(dirty)draw();sc(SYS_YIELD);}}
